  const [step, setStep] = useState(0);
  const [topic, setTopic] = useState("");

  function handleDismiss() {
    localStorage.setItem("erock_onboarding_complete", "true");
    onDismiss();
  }

  function handleNext() {
    if (step < 2) {
      setStep(step + 1);
    }
  }

