              })()}
            </div>
            <CardTitle className="text-xl">{STEPS[step].title}</CardTitle>
          </div>
        </CardHeader>

        <CardContent className="space-y-4">
          {/* Step 0: Welcome */}
          {step === 0 && (
            <>
              <p className="text-sm text-muted-foreground leading-relaxed">
                {STEPS[0].description}
              </p>
              <div className="rounded-lg bg-muted/50 p-4">
                <p className="text-sm font-medium">{STEPS[0].detail}</p>
              </div>
            </>
          )}

          {/* Step 1: Enter topic */}
          {step === 1 && (
            <>
              <p className="text-sm text-muted-foreground leading-relaxed">
                {STEPS[1].description}
              </p>
              <div className="space-y-3 pt-2">
                <input
                  type="text"
                  placeholder='e.g., "Mechanistic Interpretability of Transformer Reasoning Chains"'
                  value={topic}
                  onChange={(e) => setTopic(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && handleStart()}
                  className="flex h-12 w-full rounded-md border border-input bg-background px-4 py-3 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  data-testid="onboarding-topic-input"
                  autoFocus
                />
                <Button
                  onClick={handleStart}
                  disabled={!topic.trim()}
                  className="w-full h-11"
                  data-testid="onboarding-start-btn"
                >
                  <Sparkles className="mr-2 h-4 w-4" />
                  Start Research Pipeline
                </Button>
              </div>
            </>
          )}

          {/* Step 2: What you'll get */}
          {step === 2 && (
            <>
              <p className="text-sm text-muted-foreground leading-relaxed">
                {STEPS[2].description}
              </p>
              <ul className="space-y-2">
                {PROPOSAL_SECTIONS.map((section) => (
                  <li key={section} className="flex items-center gap-2 text-sm">
                    <div className="h-1.5 w-1.5 rounded-full bg-primary flex-shrink-0" />
                    <span>{section}</span>
                  </li>
                ))}
              </ul>
              <div className="rounded-lg bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 p-3">
                <p className="text-xs text-amber-800 dark:text-amber-200">
                  <strong>⏱ Timing:</strong> A "Quick Scan" takes ~3 minutes. A "Deep Research" run takes ~20 minutes. You can watch the progress in real-time.
                </p>
              </div>
            </>
          )}

          {/* Navigation */}
          {step !== 1 && (
            <div className="flex items-center justify-between pt-2">
              {step > 0 ? (
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setStep(step - 1)}
                >
                  Back
                </Button>
              ) : (
                <div />
              )}
              <div className="flex items-center gap-2">
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={handleDismiss}
                  data-testid="onboarding-skip-btn"
                >
                  Skip for now
                </Button>
                {step < 2 && (
                  <Button size="sm" onClick={handleNext}>
                    Next
                    <ChevronRight className="ml-1 h-4 w-4" />
                  </Button>
                )}
                {step === 2 && (
                  <Button
                    size="sm"
                    onClick={handleDismiss}
                    data-testid="onboarding-got-it"
                  >
                    <Play className="mr-2 h-4 w-4" />
                    Got it — let's go!
                  </Button>
                )}
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

